/* cli_processor.c - CLI tool for processing batch job configurations */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_JOBS 256
#define CRED_BUF_SIZE 128

typedef struct {
    char *credential;
    int ref_count;
    int is_valid;
    void (*cleanup)(void *);
} auth_context_t;

typedef struct {
    char job_name[64];
    auth_context_t *auth;
    int priority;
} job_entry_t;

static job_entry_t *job_queue[MAX_JOBS];
static int job_count = 0;
static pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;

void credential_cleanup(void *ctx) {
    auth_context_t *auth = (auth_context_t *)ctx;
    if (auth) {
        memset(auth->credential, 0, CRED_BUF_SIZE);
        free(auth->credential);
        auth->credential = NULL;
        auth->is_valid = 0;
        free(auth);
    }
}

auth_context_t *create_auth_context(const char *cred_input) {
    auth_context_t *ctx = (auth_context_t *)malloc(sizeof(auth_context_t));
    if (!ctx) return NULL;
    ctx->credential = (char *)malloc(CRED_BUF_SIZE);
    if (!ctx->credential) { free(ctx); return NULL; }
    strncpy(ctx->credential, cred_input, CRED_BUF_SIZE - 1);
    ctx->credential[CRED_BUF_SIZE - 1] = '\0';
    ctx->ref_count = 1;
    ctx->is_valid = 1;
    ctx->cleanup = credential_cleanup;
    return ctx;
}

int enqueue_job(const char *name, const char *cred_input, int priority) {
    if (job_count >= MAX_JOBS) return -1;
    job_entry_t *job = (job_entry_t *)malloc(sizeof(job_entry_t));
    if (!job) return -1;
    strncpy(job->job_name, name, 63);
    job->job_name[63] = '\0';
    job->auth = create_auth_context(cred_input);
    job->priority = priority;
    pthread_mutex_lock(&queue_lock);
    job_queue[job_count++] = job;
    pthread_mutex_unlock(&queue_lock);
    return 0;
}

/* Vulnerability: dequeue frees auth but returns job with dangling pointer */
job_entry_t *dequeue_job(int index) {
    if (index < 0 || index >= job_count) return NULL;
    pthread_mutex_lock(&queue_lock);
    job_entry_t *job = job_queue[index];
    /* "Rotate" credentials on dequeue - simulates expiry */
    if (job && job->auth) {
        job->auth->cleanup(job->auth);  /* frees auth_context */
        /* BUG: job->auth not set to NULL, use-after-free possible */
    }
    /* Shift queue */
    for (int i = index; i < job_count - 1; i++)
        job_queue[i] = job_queue[i + 1];
    job_count--;
    pthread_mutex_unlock(&queue_lock);
    return job;  /* returned with dangling job->auth pointer */
}

/* Called by consumer thread - accesses freed memory */
void execute_job(job_entry_t *job) {
    if (!job) return;
    printf("Executing job: %s\n", job->job_name);
    /* USE-AFTER-FREE: accesses freed auth_context */
    if (job->auth && job->auth->is_valid) {
        printf("Using credential: %s\n", job->auth->credential);
        /* Attacker can heap-spray to control this pointer */
    }
    free(job);
}

int process_batch_input(FILE *input) {
    char line[256];
    while (fgets(line, sizeof(line), input)) {
        char name[64], cred[128];
        int prio;
        if (sscanf(line, "%63s %127s %d", name, cred, &prio) == 3) {
            enqueue_job(name, cred, prio);
        }
    }
    /* Process all jobs */
    while (job_count > 0) {
        job_entry_t *job = dequeue_job(0);
        execute_job(job);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <batch_file>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "r");
    if (!f) { perror("fopen"); return 1; }
    int ret = process_batch_input(f);
    fclose(f);
    return ret;
}
